INSERT INTO translation VALUES
('KJV', 'King James Version', '1769 Oxford standard text', 'Public domain', 'King James Version (public domain).', 'Theographic Bible Metadata'),
('ESV', 'English Standard Version', 'ESV 2001 text (original edition), unofficial digital copy, patched', 'Copyright Crossway; used by permission', 'Scripture quotations are from the ESV® Bible (The Holy Bible, English Standard Version®), © 2001 by Crossway, a publishing ministry of Good News Publishers. Used by permission. All rights reserved.', 'Unofficial SQLite copy (github.com/BIBLE-Study/SQLite-Databases), checked against esv.org and patched'),
('BSB', 'Berean Standard Bible', 'ebible.org engbsb (2026-10-20)', 'Public domain', 'The Holy Bible, Berean Standard Bible, BSB is produced in cooperation with Bible Hub, Discovery Bible, OpenBible.com, and the Berean Bible Translation Committee. This text of God''s Word has been dedicated to the public domain.', 'ebible.org engbsb USFM'),
('NET', 'New English Translation', 'ebible.org engnet (text with minimal notes)', 'Copyright Biblical Studies Press; used by permission', 'Scripture quoted by permission. Quotations designated (NET) are from the NET Bible® copyright ©1996, 2019 by Biblical Studies Press, L.L.C. http://netbible.com All rights reserved.', 'ebible.org engnet USFM');
INSERT INTO verse_text (verse_id, translation, text, license, attribution, status, import_note) VALUES
('Gen.1.1', 'BSB', 'In the beginning God created the heavens and the earth.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.2', 'BSB', 'Now the earth was formless and void, and darkness was over the surface of the deep. And the Spirit of God was hovering over the surface of the waters.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.3', 'BSB', 'And God said, “Let there be light,” and there was light.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.4', 'BSB', 'And God saw that the light was good, and He separated the light from the darkness.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.5', 'BSB', 'God called the light “day,” and the darkness He called “night.” And there was evening, and there was morning—the first day.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.6', 'BSB', 'And God said, “Let there be an expanse between the waters, to separate the waters from the waters.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.7', 'BSB', 'So God made the expanse and separated the waters beneath it from the waters above. And it was so.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.8', 'BSB', 'God called the expanse “sky.” And there was evening, and there was morning—the second day.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.9', 'BSB', 'And God said, “Let the waters under the sky be gathered into one place, so that the dry land may appear.” And it was so.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.10', 'BSB', 'God called the dry land “earth,” and the gathering of waters He called “seas.” And God saw that it was good.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.11', 'BSB', 'Then God said, “Let the earth bring forth vegetation: seed-bearing plants and fruit trees, each bearing fruit with seed according to its kind.” And it was so.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.12', 'BSB', 'The earth produced vegetation: seed-bearing plants according to their kinds and trees bearing fruit with seed according to their kinds. And God saw that it was good.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.13', 'BSB', 'And there was evening, and there was morning—the third day.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.14', 'BSB', 'And God said, “Let there be lights in the expanse of the sky to distinguish between the day and the night, and let them be signs to mark the seasons and days and years.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.15', 'BSB', 'And let them serve as lights in the expanse of the sky to shine upon the earth.” And it was so.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.16', 'BSB', 'God made two great lights: the greater light to rule the day and the lesser light to rule the night. And He made the stars as well.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.17', 'BSB', 'God set these lights in the expanse of the sky to shine upon the earth,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.18', 'BSB', 'to preside over the day and the night, and to separate the light from the darkness. And God saw that it was good.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.19', 'BSB', 'And there was evening, and there was morning—the fourth day.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.20', 'BSB', 'And God said, “Let the waters teem with living creatures, and let birds fly above the earth in the open expanse of the sky.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.21', 'BSB', 'So God created the great sea creatures and every living thing that moves, with which the waters teemed according to their kinds, and every bird of flight after its kind. And God saw that it was good.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.22', 'BSB', 'Then God blessed them and said, “Be fruitful and multiply and fill the waters of the seas, and let birds multiply on the earth.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.23', 'BSB', 'And there was evening, and there was morning—the fifth day.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.24', 'BSB', 'And God said, “Let the earth bring forth living creatures according to their kinds: livestock, land crawlers, and beasts of the earth according to their kinds.” And it was so.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.25', 'BSB', 'God made the beasts of the earth according to their kinds, the livestock according to their kinds, and everything that crawls upon the earth according to its kind. And God saw that it was good.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.26', 'BSB', 'Then God said, “Let Us make man in Our image, after Our likeness, to rule over the fish of the sea and the birds of the air, over the livestock, and over all the earth itself and every creature that crawls upon it.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.27', 'BSB', 'So God created man in His own image; in the image of God He created him; male and female He created them.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.28', 'BSB', 'God blessed them and said to them, “Be fruitful and multiply, and fill the earth and subdue it; rule over the fish of the sea and the birds of the air and every creature that crawls upon the earth.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.29', 'BSB', 'Then God said, “Behold, I have given you every seed-bearing plant on the face of all the earth, and every tree whose fruit contains seed. They will be yours for food.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.30', 'BSB', 'And to every beast of the earth and every bird of the air and every creature that crawls upon the earth—everything that has the breath of life in it—I have given every green plant for food.” And it was so.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.1.31', 'BSB', 'And God looked upon all that He had made, and indeed, it was very good. And there was evening, and there was morning—the sixth day.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.1', 'BSB', 'Thus the heavens and the earth were completed in all their vast array.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.2', 'BSB', 'And by the seventh day God had finished the work He had been doing; so on that day He rested from all His work.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.3', 'BSB', 'Then God blessed the seventh day and sanctified it, because on that day He rested from all the work of creation that He had accomplished.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.4', 'BSB', 'This is the account of the heavens and the earth when they were created, in the day that the LORD God made them.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.5', 'BSB', 'Now no shrub of the field had yet appeared on the earth, nor had any plant of the field sprouted; for the LORD God had not yet sent rain upon the earth, and there was no man to cultivate the ground.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.6', 'BSB', 'But springs welled up from the earth and watered the whole surface of the ground.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.7', 'BSB', 'Then the LORD God formed man from the dust of the ground and breathed the breath of life into his nostrils, and the man became a living being.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.8', 'BSB', 'And the LORD God planted a garden in Eden, in the east, where He placed the man He had formed.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.9', 'BSB', 'Out of the ground the LORD God gave growth to every tree that is pleasing to the eye and good for food. And in the middle of the garden were the tree of life and the tree of the knowledge of good and evil.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.10', 'BSB', 'Now a river flowed out of Eden to water the garden, and from there it branched into four headwaters:', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.11', 'BSB', 'The name of the first river is Pishon; it winds through the whole land of Havilah, where there is gold.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.12', 'BSB', 'And the gold of that land is pure, and bdellium and onyx are found there.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.13', 'BSB', 'The name of the second river is Gihon; it winds through the whole land of Cush.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.14', 'BSB', 'The name of the third river is Hiddekel; it runs along the east side of Assyria. And the fourth river is the Euphrates.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.15', 'BSB', 'Then the LORD God took the man and placed him in the Garden of Eden to cultivate and keep it.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.16', 'BSB', 'And the LORD God commanded him, “You may eat freely from every tree of the garden,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.17', 'BSB', 'but you must not eat from the tree of the knowledge of good and evil; for in the day that you eat of it, you will surely die.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.18', 'BSB', 'The LORD God also said, “It is not good for the man to be alone. I will make for him a suitable helper.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.19', 'BSB', 'And out of the ground the LORD God formed every beast of the field and every bird of the air, and He brought them to the man to see what he would name each one. And whatever the man called each living creature, that was its name.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.20', 'BSB', 'The man gave names to all the livestock, to the birds of the air, and to every beast of the field. But for Adam no suitable helper was found.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.21', 'BSB', 'So the LORD God caused the man to fall into a deep sleep, and while he slept, He took one of the man’s ribs and closed up the area with flesh.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.22', 'BSB', 'And from the rib that the LORD God had taken from the man, He made a woman and brought her to him.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.23', 'BSB', 'And the man said: “This is now bone of my bones and flesh of my flesh; she shall be called ‘woman,’ for out of man she was taken.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.24', 'BSB', 'For this reason a man will leave his father and mother and be united to his wife, and they will become one flesh.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.2.25', 'BSB', 'And the man and his wife were both naked, and they were not ashamed.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.1', 'BSB', 'Now the serpent was more crafty than any beast of the field that the LORD God had made. And he said to the woman, “Did God really say, ‘You must not eat from any tree in the garden?’”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.2', 'BSB', 'The woman answered the serpent, “We may eat the fruit of the trees of the garden,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.3', 'BSB', 'but about the fruit of the tree in the middle of the garden, God has said, ‘You must not eat of it or touch it, or you will die.’”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.4', 'BSB', '“You will not surely die,” the serpent told her.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.5', 'BSB', '“For God knows that in the day you eat of it, your eyes will be opened and you will be like God, knowing good and evil.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.6', 'BSB', 'When the woman saw that the tree was good for food and pleasing to the eyes, and that it was desirable for obtaining wisdom, she took the fruit and ate it. She also gave some to her husband who was with her, and he ate it.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.7', 'BSB', 'And the eyes of both of them were opened, and they knew that they were naked; so they sewed together fig leaves and made coverings for themselves.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.8', 'BSB', 'Then the man and his wife heard the voice of the LORD God walking in the garden in the breeze of the day, and they hid themselves from the presence of the LORD God among the trees of the garden.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.9', 'BSB', 'But the LORD God called out to the man, “Where are you?”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.10', 'BSB', '“I heard Your voice in the garden,” he replied, “and I was afraid because I was naked; so I hid myself.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.11', 'BSB', '“Who told you that you were naked?” asked the LORD God. “Have you eaten from the tree of which I commanded you not to eat?”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.12', 'BSB', 'And the man answered, “The woman whom You gave me, she gave me fruit from the tree, and I ate it.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.13', 'BSB', 'Then the LORD God said to the woman, “What is this you have done?” “The serpent deceived me,” she replied, “and I ate.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.14', 'BSB', 'So the LORD God said to the serpent: “Because you have done this, cursed are you above all livestock and every beast of the field! On your belly will you go, and dust you will eat, all the days of your life.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.15', 'BSB', 'And I will put enmity between you and the woman, and between your seed and her seed. He will crush your head, and you will strike his heel.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.16', 'BSB', 'To the woman He said: “I will sharply increase your pain in childbirth; in pain you will bring forth children. Your desire will be for your husband, and he will rule over you.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.17', 'BSB', 'And to Adam He said: “Because you have listened to the voice of your wife and have eaten from the tree of which I commanded you not to eat, cursed is the ground because of you; through toil you will eat of it all the days of your life.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.18', 'BSB', 'Both thorns and thistles it will yield for you, and you will eat the plants of the field.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.19', 'BSB', 'By the sweat of your brow you will eat your bread, until you return to the ground— because out of it were you taken. For dust you are, and to dust you shall return.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.20', 'BSB', 'And Adam named his wife Eve, because she would be the mother of all the living.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.21', 'BSB', 'And the LORD God made garments of skin for Adam and his wife, and He clothed them.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.22', 'BSB', 'Then the LORD God said, “Behold, the man has become like one of Us, knowing good and evil. And now, lest he reach out his hand and take also from the tree of life, and eat, and live forever...”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.23', 'BSB', 'Therefore the LORD God banished him from the Garden of Eden to work the ground from which he had been taken.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.3.24', 'BSB', 'So He drove out the man and stationed cherubim on the east side of the Garden of Eden, along with a whirling sword of flame to guard the way to the tree of life.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.1', 'BSB', 'And Adam had relations with his wife Eve, and she conceived and gave birth to Cain. “With the help of the LORD I have brought forth a man,” she said.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.2', 'BSB', 'Later she gave birth to Cain’s brother Abel. Now Abel was a keeper of sheep, while Cain was a tiller of the soil.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.3', 'BSB', 'So in the course of time, Cain brought some of the fruit of the soil as an offering to the LORD,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.4', 'BSB', 'while Abel brought the best portions of the firstborn of his flock. And the LORD looked with favor on Abel and his offering,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.5', 'BSB', 'but He had no regard for Cain and his offering. So Cain became very angry, and his countenance fell.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.6', 'BSB', '“Why are you angry,” said the LORD to Cain, “and why has your countenance fallen?', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.7', 'BSB', 'If you do what is right, will you not be accepted? But if you refuse to do what is right, sin is crouching at your door; it desires you, but you must master it.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.8', 'BSB', 'Then Cain said to his brother Abel, “Let us go out to the field.” And while they were in the field, Cain rose up against his brother Abel and killed him.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.9', 'BSB', 'And the LORD said to Cain, “Where is your brother Abel?” “I do not know!” he answered. “Am I my brother’s keeper?”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.10', 'BSB', '“What have you done?” replied the LORD. “The voice of your brother’s blood cries out to Me from the ground.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.11', 'BSB', 'Now you are cursed and banished from the ground, which has opened its mouth to receive your brother’s blood from your hand.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.12', 'BSB', 'When you till the ground, it will no longer yield its produce to you. You will be a fugitive and a wanderer on the earth.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.13', 'BSB', 'But Cain said to the LORD, “My punishment is greater than I can bear.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.14', 'BSB', 'Behold, this day You have driven me from the face of the earth, and from Your face I will be hidden; I will be a fugitive and a wanderer on the earth, and whoever finds me will kill me.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.15', 'BSB', '“Not so!” replied the LORD. “If anyone slays Cain, then Cain will be avenged sevenfold.” And the LORD placed a mark on Cain, so that no one who found him would kill him.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.16', 'BSB', 'So Cain went out from the presence of the LORD and settled in the land of Nod, east of Eden.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.17', 'BSB', 'And Cain had relations with his wife, and she conceived and gave birth to Enoch. Then Cain built a city and named it after his son Enoch.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.18', 'BSB', 'Now to Enoch was born Irad, and Irad was the father of Mehujael, and Mehujael was the father of Methusael, and Methusael was the father of Lamech.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.19', 'BSB', 'And Lamech married two women, one named Adah and the other Zillah.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.20', 'BSB', 'Adah gave birth to Jabal; he was the father of those who dwell in tents and raise livestock.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.21', 'BSB', 'And his brother’s name was Jubal; he was the father of all who play the harp and flute.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.22', 'BSB', 'And Zillah gave birth to Tubal-cain, a forger of every implement of bronze and iron. And the sister of Tubal-cain was Naamah.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.23', 'BSB', 'Then Lamech said to his wives: “Adah and Zillah, hear my voice; wives of Lamech, listen to my speech. For I have slain a man for wounding me, a young man for striking me.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.24', 'BSB', 'If Cain is avenged sevenfold, then Lamech seventy-sevenfold.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.25', 'BSB', 'And Adam again had relations with his wife, and she gave birth to a son and named him Seth, saying, “God has granted me another seed in place of Abel, since Cain killed him.”', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.4.26', 'BSB', 'And to Seth also a son was born, and he called him Enosh. At that time men began to call upon the name of the LORD.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Gen.5.1', 'BSB', 'This is the book of the generations of Adam. In the day that God created man, He made him in His own likeness.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
