('Neh.7.51', 'BSB', 'the descendants of Gazzam, the descendants of Uzza, the descendants of Paseah,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Neh.7.52', 'BSB', 'the descendants of Besai, the descendants of Meunim, the descendants of Nephushesim,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Neh.7.53', 'BSB', 'the descendants of Bakbuk, the descendants of Hakupha, the descendants of Harhur,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Neh.7.54', 'BSB', 'the descendants of Bazlith, the descendants of Mehida, the descendants of Harsha,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Neh.7.55', 'BSB', 'the descendants of Barkos, the descendants of Sisera, the descendants of Temah,', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
