('Ps.116.12', 'BSB', 'How can I repay the LORD for all His goodness to me?', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.116.13', 'BSB', 'I will lift the cup of salvation and call on the name of the LORD.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.116.14', 'BSB', 'I will fulfill my vows to the LORD in the presence of all His people.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
