('Ps.119.16', 'BSB', 'I will delight in Your statutes; I will not forget Your word.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.17', 'BSB', 'Deal bountifully with Your servant, that I may live and keep Your word.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.18', 'BSB', 'Open my eyes that I may see wondrous things from Your law.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.19', 'BSB', 'I am a stranger on the earth; do not hide Your commandments from me.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
