('Ps.119.29', 'BSB', 'Remove me from the path of deceit and graciously grant me Your law.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.30', 'BSB', 'I have chosen the way of truth; I have set Your ordinances before me.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.31', 'BSB', 'I cling to Your testimonies, O LORD; let me not be put to shame.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.32', 'BSB', 'I run in the path of Your commandments, for You will enlarge my heart.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
