('Ps.119.47', 'BSB', 'I delight in Your commandments because I love them.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.48', 'BSB', 'I lift up my hands to Your commandments, which I love, and I meditate on Your statutes.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.49', 'BSB', 'Remember Your word to Your servant, upon which You have given me hope.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.50', 'BSB', 'This is my comfort in affliction, that Your promise has given me life.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.51', 'BSB', 'The arrogant utterly deride me, but I do not turn from Your law.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
