('Ps.119.57', 'BSB', 'The LORD is my portion; I have promised to keep Your words.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
('Ps.119.58', 'BSB', 'I have sought Your face with all my heart; be gracious to me according to Your promise.', 'Public domain', 'Berean Standard Bible (BSB); full notice in bible.translation', 'as imported', NULL),
