INSERT INTO note (note_id, translation, verse_id, seq, anchor, label, kind, text, display_name) VALUES
('BSB-Gen-1-3-1', 'BSB', 'Gen.1.3', 1, 'light', NULL, 'citation', 'Cited in 2 Corinthians 4:6', 'Citation: Cited in 2 Corinthians 4:6'),
('BSB-Gen-1-5-1', 'BSB', 'Gen.1.5', 1, 'day', NULL, 'literal meaning', 'Literally day one', 'Literal meaning: Literally day one'),
('BSB-Gen-1-6-1', 'BSB', 'Gen.1.6', 1, 'expanse', NULL, 'alternative rendering', 'Or a canopy or a firmament or a vault; also in verses 7, 8, 14, 15, 17, and 20', 'Alternative rendering: Or a canopy or a firmament or a vault; also in verses 7, 8, 14,...'),
('BSB-Gen-1-26-1', 'BSB', 'Gen.1.26', 1, 'itself', NULL, 'manuscript variant', 'MT; Syriac and over all the beasts of the earth', 'Manuscript variant: MT; Syriac and over all the beasts of the earth'),
('BSB-Gen-1-27-1', 'BSB', 'Gen.1.27', 1, 'them', NULL, 'citation', 'Cited in Matthew 19:4 and Mark 10:6', 'Citation: Cited in Matthew 19:4 and Mark 10:6'),
('BSB-Gen-2-2-1', 'BSB', 'Gen.2.2', 1, 'work', NULL, 'citation', 'Cited in Hebrews 4:4', 'Citation: Cited in Hebrews 4:4'),
('BSB-Gen-2-4-1', 'BSB', 'Gen.2.4', 1, 'LORD', NULL, 'explanation', 'LORD or GOD, with capital letters, represents the proper name of the God of Israel and the one true God, transliterated from the Hebrew as YHWH; here and throughout the Scriptures.', 'Explanation: LORD or GOD, with capital letters, represents the proper name of...'),
('BSB-Gen-2-6-1', 'BSB', 'Gen.2.6', 1, 'springs', NULL, 'alternative rendering', 'Or mist', 'Alternative rendering: Or mist'),
('BSB-Gen-2-7-1', 'BSB', 'Gen.2.7', 1, 'being', NULL, 'alternative rendering', 'Or a living soul; cited in 1 Corinthians 15:45', 'Alternative rendering: Or a living soul; cited in 1 Corinthians 15:45'),
('BSB-Gen-2-20-1', 'BSB', 'Gen.2.20', 1, 'Adam', NULL, 'alternative rendering', 'Or the man, as in verses 19 and 21', 'Alternative rendering: Or the man, as in verses 19 and 21'),
('BSB-Gen-2-21-1', 'BSB', 'Gen.2.21', 1, 'ribs', NULL, 'alternative rendering', 'Or took part of the man’s side; similarly in verse 22', 'Alternative rendering: Or took part of the man’s side; similarly in verse 22'),
('BSB-Gen-2-24-1', 'BSB', 'Gen.2.24', 1, 'flesh', NULL, 'manuscript variant', 'LXX and the two will become one flesh; cited in Matthew 19:5, Mark 10:7–8, 1 Corinthians 6:16, and Ephesians 5:31', 'Manuscript variant: LXX and the two will become one flesh; cited in Matthew 19:5, Mark...'),
('BSB-Gen-3-1-1', 'BSB', 'Gen.3.1', 1, 'serpent', NULL, 'literal meaning', 'Hebrew nachash, translated in this chapter as serpent, is translated in most cases as snake.', 'Literal meaning: Hebrew nachash, translated in this chapter as serpent, is...'),
('BSB-Gen-3-8-1', 'BSB', 'Gen.3.8', 1, 'breeze', NULL, 'alternative rendering', 'Or at the breezy (time); Hebrew unto the Ruach', 'Alternative rendering: Or at the breezy; Hebrew unto the Ruach'),
('BSB-Gen-3-15-1', 'BSB', 'Gen.3.15', 1, 'heel', NULL, 'alternative rendering', 'Or He will bruise your head, and you will bruise his heel. The same Hebrew root for crush, bruise, or strike appears twice in this verse.', 'Alternative rendering: Or He will bruise your head, and you will bruise his heel. The...'),
('BSB-Gen-3-16-1', 'BSB', 'Gen.3.16', 1, 'husband', NULL, 'alternative rendering', 'Or You will desire to control your husband', 'Alternative rendering: Or You will desire to control your husband'),
('BSB-Gen-3-20-1', 'BSB', 'Gen.3.20', 1, 'Eve', NULL, 'explanation', 'Eve sounds like the Hebrew for giving life or living.', 'Explanation: Eve sounds like the Hebrew for giving life or living.'),
('BSB-Gen-4-1-1', 'BSB', 'Gen.4.1', 1, 'Cain', NULL, 'explanation', 'Cain sounds like the Hebrew for acquired or brought forth.', 'Explanation: Cain sounds like the Hebrew for acquired or brought forth.'),
('BSB-Gen-4-7-1', 'BSB', 'Gen.4.7', 1, 'you', NULL, 'alternative rendering', 'Or it desires to control you', 'Alternative rendering: Or it desires to control you'),
('BSB-Gen-4-8-1', 'BSB', 'Gen.4.8', 1, 'field', NULL, 'manuscript variant', 'SP, LXX, Syriac, and Vulgate; Hebrew Then Cain spoke to his brother Abel.', 'Manuscript variant: SP, LXX, Syriac, and Vulgate; Hebrew Then Cain spoke to his...'),
('BSB-Gen-4-13-1', 'BSB', 'Gen.4.13', 1, 'punishment', NULL, 'alternative rendering', 'Or guilt or sin', 'Alternative rendering: Or guilt or sin'),
('BSB-Gen-4-15-1', 'BSB', 'Gen.4.15', 1, 'so', NULL, 'manuscript variant', 'LXX, Vulgate, and Syriac; Hebrew “Very well!” or “Therefore:”', 'Manuscript variant: LXX, Vulgate, and Syriac; Hebrew “Very well!” or “Therefore:”'),
('BSB-Gen-4-16-1', 'BSB', 'Gen.4.16', 1, 'Nod', NULL, 'explanation', 'Nod means wandering.', 'Explanation: Nod means wandering.'),
('BSB-Gen-4-24-1', 'BSB', 'Gen.4.24', 1, 'sevenfold', NULL, 'literal meaning', 'Hebrew; LXX can be translated as either seventy times seven or seventy-sevenfold; see also Matthew 18:22.', 'Literal meaning: Hebrew; LXX can be translated as either seventy times seven or...'),
('BSB-Gen-4-25-1', 'BSB', 'Gen.4.25', 1, 'Seth', NULL, 'explanation', 'Seth probably means granted or appointed.', 'Explanation: Seth probably means granted or appointed.'),
('BSB-Gen-4-26-1', 'BSB', 'Gen.4.26', 1, 'upon', NULL, 'alternative rendering', 'Or to proclaim; some translators to invoke or to call themselves by or to profane', 'Alternative rendering: Or to proclaim; some translators to invoke or to call themselves...'),
('BSB-Gen-5-2-1', 'BSB', 'Gen.5.2', 1, 'them', NULL, 'citation', 'Cited in Matthew 19:4 and Mark 10:6', 'Citation: Cited in Matthew 19:4 and Mark 10:6'),
('BSB-Gen-5-2-2', 'BSB', 'Gen.5.2', 2, 'man', NULL, 'literal meaning', 'Hebrew Adam', 'Literal meaning: Hebrew Adam'),
('BSB-Gen-5-22-1', 'BSB', 'Gen.5.22', 1, 'God', NULL, 'manuscript variant', 'LXX pleased God; also in verse 24', 'Manuscript variant: LXX pleased God; also in verse 24'),
('BSB-Gen-5-24-1', 'BSB', 'Gen.5.24', 1, 'away', NULL, 'manuscript variant', 'LXX and he was not found, because God had taken him away; cited in Hebrews 11:5', 'Manuscript variant: LXX and he was not found, because God had taken him away; cited in...'),
('BSB-Gen-5-29-1', 'BSB', 'Gen.5.29', 1, 'Noah', NULL, 'explanation', 'Noah sounds like the Hebrew for rest or comfort.', 'Explanation: Noah sounds like the Hebrew for rest or comfort.'),
('BSB-Gen-6-3-1', 'BSB', 'Gen.6.3', 1, 'forever', NULL, 'manuscript variant', 'LXX and Syriac My Spirit will not remain in man forever', 'Manuscript variant: LXX and Syriac My Spirit will not remain in man forever'),
('BSB-Gen-6-12-1', 'BSB', 'Gen.6.12', 1, 'creatures', NULL, 'literal meaning', 'Literally all flesh; similarly in verses 13, 17, and 19', 'Literal meaning: Literally all flesh; similarly in verses 13, 17, and 19'),
('BSB-Gen-6-14-1', 'BSB', 'Gen.6.14', 1, 'wood', NULL, 'explanation', 'Gopher is an unknown kind of tree; possibly cypress or cedar.', 'Explanation: Gopher is an unknown kind of tree; possibly cypress or cedar.'),
('BSB-Gen-6-15-1', 'BSB', 'Gen.6.15', 1, 'high', NULL, 'measurement', 'The ark was approximately 450 feet long, 75 feet wide, and 45 feet high (137.2 meters long, 22.9 meters wide, and 13.7 meters high).', 'Measurement: The ark was approximately 450 feet long, 75 feet wide, and 45 feet...'),
('BSB-Gen-6-16-1', 'BSB', 'Gen.6.16', 1, 'roof', NULL, 'alternative rendering', 'Or skylight or window', 'Alternative rendering: Or skylight or window'),
('BSB-Gen-6-16-2', 'BSB', 'Gen.6.16', 2, 'top', NULL, 'measurement', 'A cubit is approximately 18 inches or 45.7 centimeters.', 'Measurement: A cubit is approximately 18 inches or 45.7 centimeters.'),
('BSB-Gen-7-2-1', 'BSB', 'Gen.7.2', 1, 'of', NULL, 'alternative rendering', 'Or by sevens; also in verse 3', 'Alternative rendering: Or by sevens; also in verse 3'),
('BSB-Gen-7-15-1', 'BSB', 'Gen.7.15', 1, 'creature', NULL, 'literal meaning', 'Literally of all flesh; similarly in verses 16 and 21', 'Literal meaning: Literally of all flesh; similarly in verses 16 and 21'),
('BSB-Gen-7-20-1', 'BSB', 'Gen.7.20', 1, 'cubits', NULL, 'measurement', '15 cubits is approximately 22.5 feet or 6.9 meters.', 'Measurement: 15 cubits is approximately 22.5 feet or 6.9 meters.'),
('BSB-Gen-8-8-1', 'BSB', 'Gen.8.8', 1, 'out', NULL, 'literal meaning', 'Literally sent out from him or sent out from it', 'Literal meaning: Literally sent out from him or sent out from it'),
('BSB-Gen-9-20-1', 'BSB', 'Gen.9.20', 1, 'proceeded', NULL, 'alternative rendering', 'Or was the first', 'Alternative rendering: Or was the first'),
('BSB-Gen-9-27-1', 'BSB', 'Gen.9.27', 1, 'Japheth', NULL, 'explanation', 'Japheth sounds like the Hebrew for expand.', 'Explanation: Japheth sounds like the Hebrew for expand.'),
